def _configure_process_runtime_environment() -> None:
    """Configure fork-safe numerical runtimes before NumPy/Numba imports."""
    raw_nproc = os.environ.get("NPROC", str(DEFAULT_NPROC)).strip()
    try:
        nproc = max(1, int(float(raw_nproc)))
    except Exception:
        nproc = max(1, int(DEFAULT_NPROC))
    nested = str(os.environ.get("ALLOW_NESTED_PARALLELISM", "0")).strip().lower() in {
        "1", "true", "yes", "y", "on",
    }

    cache_base = (
        os.environ.get("LF_RUNTIME_CACHE_DIR", "").strip()
        or os.environ.get("TMPDIR", "").strip()
        or "/tmp"
    )
    project_identity = str(Path(__file__).resolve().parent.parent)
    project_tag = f"{zlib.crc32(project_identity.encode('utf-8')) & 0xffffffff:08x}"
    runtime_root = Path(cache_base).expanduser() / (
        f"licketyfit-{os.getuid()}-{project_tag}-"
        f"py{sys.version_info.major}{sys.version_info.minor}"
    )
    try:
        numba_cache = runtime_root / "numba"
        native_cache = runtime_root / "native"
        numba_cache.mkdir(parents=True, exist_ok=True)
        native_cache.mkdir(parents=True, exist_ok=True)
        os.environ.setdefault("NUMBA_CACHE_DIR", str(numba_cache))
        os.environ.setdefault("LF_NATIVE_CACHE_DIR", str(native_cache))
        os.environ.setdefault("LF_RESOLVED_RUNTIME_CACHE_DIR", str(runtime_root))
    except OSError:
        pass

    if nproc > 1 and not nested:
        os.environ.setdefault("NUMBA_THREADING_LAYER", "forksafe")
        os.environ["OPENBLAS_NUM_THREADS"] = "1"
        os.environ["MKL_NUM_THREADS"] = "1"
        os.environ["NUMEXPR_NUM_THREADS"] = "1"
        os.environ["OMP_NUM_THREADS"] = "1"
        os.environ["OMP_DYNAMIC"] = "FALSE"


def _receiver_status_without_prefork_native_load(
    emitter,
    p_locations,
    pmt_normals,
    *,
    status_function,
    native_library_path,
    nproc: int,
):
    """Inspect receiver compatibility without dlopen'ing libgomp pre-fork."""
    requested = bool(getattr(emitter, "photon_scatter_native_receiver", False))
    if int(nproc) <= 1 or not requested:
        status = dict(status_function(emitter, p_locations, pmt_normals))
        status["native_receiver_probe_mode"] = "runtime_load_no_later_fork"
        return status

    setattr(emitter, "photon_scatter_native_receiver", False)
    try:
        status = dict(status_function(emitter, p_locations, pmt_normals))
    finally:
        setattr(emitter, "photon_scatter_native_receiver", requested)
    built = bool(
        native_library_path is not None
        and Path(native_library_path).is_file()
    )
    status.update({
        "native_receiver_requested": True,
        "native_receiver_available": built,
        "native_receiver_probe_mode": "build_only_before_fork",
        "native_receiver_library_path": (
            None if native_library_path is None else str(native_library_path)
        ),
        "native_receiver_first_load_location": "forked_event_worker",
    })
    return status

_VALID_DATA_SOURCES = {"wcsim", "wcte"}
_VALID_FIT_MODES = {"full_length", "absorption", "cosmic"}


def _normalize_choice(value: str, allowed: set[str], label: str) -> str:
    normalized = str(value).strip().lower().replace("-", "_")
    if normalized not in allowed:
        choices = ", ".join(sorted(allowed))
        raise ValueError(f"{label} must be one of: {choices}")
    return normalized


def _setdefault_text(name: str, value) -> None:
    if value is None:
        return
    os.environ.setdefault(name, str(value))


def _truthy_text(value) -> bool:
    return str(value).strip().lower() in {"1", "true", "yes", "y", "on"}


def _selection_cut_specs_from_env(name: str, default) -> tuple[tuple[object, object, object], ...]:
    """Parse BeamSelection cut triplets from a JSON environment override."""
    raw = os.environ.get(name)
    value = default if raw is None or not str(raw).strip() else json.loads(str(raw))
    if value is None:
        return ()
    if not isinstance(value, (list, tuple)):
        raise ValueError(f"{name} must be a JSON list of [variable, operator, value] cuts")
    result = []
    for spec in value:
        if not isinstance(spec, (list, tuple)) or len(spec) != 3:
            raise ValueError(
                f"{name} entries must be [variable, operator, value]; got {spec!r}"
            )
        variable, operator, cut_value = spec
        if isinstance(cut_value, tuple):
            cut_value = list(cut_value)
        result.append((variable, operator, cut_value))
    return tuple(result)


_WCTE_SELECTION_PARTICLE_ALIASES = {
    "mu": "muon", "mu-": "muon", "mu+": "muon", "muon": "muon",
    "pi": "pion", "pi-": "pion", "pi+": "pion", "pion": "pion",
    "e": "electron", "e-": "electron", "e+": "electron", "electron": "electron",
    "k": "kaon", "k-": "kaon", "k+": "kaon", "kaon": "kaon",
    "p": "proton", "p+": "proton", "proton": "proton",
}
_ELECTRON_FIT_ALIASES = frozenset({"e", "e-", "e+", "electron"})


def _validate_wcte_particle_selection_contract(
    *,
    fit_particle_raw: str,
    selection_label: str,
    selection_mode: str,
    extra_selection_cuts,
    loader_active: bool = True,
) -> str:
    """Validate the deliberately separate selected-population and fit hypotheses."""
    fit_raw = str(fit_particle_raw).strip().lower()
    if fit_raw in _ELECTRON_FIT_ALIASES:
        raise ValueError(
            "analysis_tools can select electron beam events, but LicketyFit does "
            "not yet implement an electron range/cone fit hypothesis. Set "
            "PARTICLE_SELECTION_LABEL='electron' and choose an explicit supported "
            "FIT_PARTICLE (muon, pion, kaon, or proton) for a hypothesis test."
        )
    selection_key = str(selection_label).strip().lower()
    try:
        selection_particle = _WCTE_SELECTION_PARTICLE_ALIASES[selection_key]
    except KeyError as exc:
        raise ValueError(
            f"Unsupported PARTICLE_SELECTION_LABEL={selection_label!r}; expected "
            "muon, pion, electron, kaon, or proton."
        ) from exc
    mode = str(selection_mode).strip().lower().replace("-", "_")
    if mode not in {"nominal", "custom"}:
        raise ValueError("WCTE_SELECTION_MODE must be nominal or custom")
    if loader_active and selection_particle == "kaon" and mode != "custom":
        raise ValueError(
            "analysis_tools defines no nominal kaon BeamSelection. For a kaon fit, "
            "set WCTE_SELECTION_MODE='custom' and provide explicit "
            "DEFAULT_WCTE_EXTRA_SELECTION_CUTS / WCTE_EXTRA_SELECTION_CUTS_JSON."
        )
    if loader_active and mode == "custom" and not tuple(extra_selection_cuts):
        raise ValueError(
            "WCTE_SELECTION_MODE='custom' requires at least one explicit "
            "BeamSelection cut in WCTE_EXTRA_SELECTION_CUTS_JSON (or the driver default)."
        )
    return selection_particle


def _selection_matches_fit_hypothesis(
    selection_particle: str, fit_particle: str
) -> bool:
    return str(selection_particle) == str(fit_particle)


def _apply_unified_defaults() -> tuple[str, str]:
    _configure_process_runtime_environment()
    source = _normalize_choice(
        os.environ.get("LF_DATA_SOURCE", os.environ.get("DATA_SOURCE", DEFAULT_DATA_SOURCE)),
        _VALID_DATA_SOURCES,
        "DATA_SOURCE/LF_DATA_SOURCE",
    )
    mode = _normalize_choice(
        os.environ.get("FIT_MODE", DEFAULT_FIT_MODE),
        _VALID_FIT_MODES,
        "FIT_MODE",
    )
    os.environ["LF_DATA_SOURCE"] = source
    os.environ["FIT_MODE"] = mode

    # Record whether the resolved truth setting came from the user's shell or
    # from the edited driver defaults.  Environment variables intentionally
    # retain precedence, but that precedence must not be silent because an old
    # ``WCSIM_USE_TRUTH_ROOT=0`` export can otherwise make a newly edited
    # ``DEFAULT_WCSIM_USE_TRUTH_ROOT=True`` appear ineffective.  The marker is
    # inherited unchanged by supervised children.
    if "LF_WCSIM_TRUTH_USE_SOURCE" not in os.environ:
        os.environ["LF_WCSIM_TRUTH_USE_SOURCE"] = (
            "environment" if "WCSIM_USE_TRUTH_ROOT" in os.environ
            else "driver_default"
        )
    if "LF_WCSIM_TRUTH_ROOT_FILE_SOURCE" not in os.environ:
        os.environ["LF_WCSIM_TRUTH_ROOT_FILE_SOURCE"] = (
            "environment" if "WCSIM_TRUTH_ROOT_FILE" in os.environ
            else "driver_default"
        )

    truth_requested = _truthy_text(
        os.environ.get("WCSIM_USE_TRUTH_ROOT", DEFAULT_WCSIM_USE_TRUTH_ROOT)
    )
    if source != "wcsim" and truth_requested:
        raise ValueError(
            "WCSim truth ROOT input is not available for DATA_SOURCE=wcte. "
            "Set WCSIM_USE_TRUTH_ROOT=0 for real data."
        )

    # Prefer the geometry repository bundled beside LicketyFit_official.  This
    # makes the frozen package self-contained while still allowing an explicit
    # GEOMETRY_PATH environment override for another detector repository.
    package_root = Path(__file__).resolve().parents[2]
    bundled_geometry = package_root / "geometry_repository"
    if bundled_geometry.is_dir():
        _setdefault_text("GEOMETRY_PATH", str(bundled_geometry))

    _setdefault_text("FIT_PARTICLE", DEFAULT_FIT_PARTICLE)
    _setdefault_text("NPROC", int(DEFAULT_NPROC))
    _setdefault_text("LF_PUBLIC_DRIVER_RELEASE", UNIFIED_DRIVER_RELEASE)
    if str(DEFAULT_OUTPUT_FILE).strip():
        _setdefault_text("LF_OUTPUT_FILE", str(DEFAULT_OUTPUT_FILE).strip())

    if source == "wcsim":
        _setdefault_text("TOT_EVENTS", int(DEFAULT_WCSIM_N_EVENTS))
        _setdefault_text("LIKELIHOOD_MODE", DEFAULT_WCSIM_LIKELIHOOD_MODE)
        _setdefault_text("ENERGY_TRUE", repr(float(DEFAULT_WCSIM_ENERGY_LABEL_MEV)))
        _setdefault_text("LF_WCTE", "1" if DEFAULT_USE_WCTE_GEOMETRY else "0")
        _setdefault_text("LF_IWCD", "1" if DEFAULT_USE_IWCD_GEOMETRY else "0")
        _setdefault_text(
            "WCSIM_USE_TRUTH_ROOT",
            "1" if DEFAULT_WCSIM_USE_TRUTH_ROOT else "0",
        )
        _setdefault_text("WCSIM_TRUTH_TREE", DEFAULT_WCSIM_TRUTH_TREE)
        _setdefault_text(
            "WCSIM_TRUTH_EVENT_ID_OFFSET",
            int(DEFAULT_WCSIM_TRUTH_EVENT_ID_OFFSET),
        )
        if DEFAULT_WCSIM_TRUTH_POSITION_OFFSET_MM is not None:
            _setdefault_text(
                "WCSIM_TRUTH_POSITION_OFFSET_MM",
                ",".join(str(float(value)) for value in DEFAULT_WCSIM_TRUTH_POSITION_OFFSET_MM),
            )
        if DEFAULT_WCSIM_TRUTH_PRIMARY_TRACK_ID is not None:
            _setdefault_text(
                "WCSIM_TRUTH_PRIMARY_TRACK_ID",
                int(DEFAULT_WCSIM_TRUTH_PRIMARY_TRACK_ID),
            )
        _setdefault_text(
            "WCSIM_TRUTH_UPROOT_STEP_SIZE",
            DEFAULT_WCSIM_TRUTH_UPROOT_STEP_SIZE,
        )
        _setdefault_text(
            "WCSIM_TRUTH_EVENT_INDEX_STEP_SIZE",
            DEFAULT_WCSIM_TRUTH_EVENT_INDEX_STEP_SIZE,
        )
        _setdefault_text(
            "WCSIM_TRUTH_IO_WORKERS",
            int(DEFAULT_WCSIM_TRUTH_IO_WORKERS),
        )
        _setdefault_text(
            "WCSIM_TRUTH_USE_EVENT_INDEX_CACHE",
            "1" if DEFAULT_WCSIM_TRUTH_USE_EVENT_INDEX_CACHE else "0",
        )
        _setdefault_text(
            "WCSIM_TRUTH_INCLUDE_OPTIONAL_DETAILS",
            "1" if DEFAULT_WCSIM_TRUTH_INCLUDE_OPTIONAL_DETAILS else "0",
        )
        if str(DEFAULT_WCSIM_TRUTH_INDEX_CACHE_DIR).strip():
            _setdefault_text(
                "WCSIM_TRUTH_INDEX_CACHE_DIR",
                str(DEFAULT_WCSIM_TRUTH_INDEX_CACHE_DIR).strip(),
            )
        if str(DEFAULT_WCSIM_TRUTH_ROOT_FILE).strip():
            _setdefault_text(
                "WCSIM_TRUTH_ROOT_FILE",
                str(DEFAULT_WCSIM_TRUTH_ROOT_FILE).strip(),
            )
        if str(DEFAULT_WCSIM_INPUT_FILE).strip():
            _setdefault_text("WCSIM_INPUT_FILE", str(DEFAULT_WCSIM_INPUT_FILE).strip())
    else:
        _setdefault_text("RUN", int(DEFAULT_WCTE_RUN))
        _setdefault_text("N_EVENTS", int(DEFAULT_WCTE_N_ROOT_ENTRIES))
        _setdefault_text("N_ROOT_ENTRIES", int(DEFAULT_WCTE_N_ROOT_ENTRIES))
        if DEFAULT_WCTE_MAX_EVENTS_TO_FIT is not None:
            _setdefault_text("MAX_EVENTS_TO_FIT", int(DEFAULT_WCTE_MAX_EVENTS_TO_FIT))
            _setdefault_text("TOT_EVENTS", int(DEFAULT_WCTE_MAX_EVENTS_TO_FIT))
        _setdefault_text("EVENT_SOURCE", DEFAULT_WCTE_EVENT_SOURCE)
        _setdefault_text("WCTE_GOOD_PMT_SOURCE", DEFAULT_WCTE_GOOD_PMT_SOURCE)
        _setdefault_text(
            "WCTE_STRICT_USER_EVENT_VALIDATION",
            "1" if DEFAULT_WCTE_STRICT_USER_EVENT_VALIDATION else "0",
        )
        _setdefault_text("LIKELIHOOD_MODE", DEFAULT_WCTE_LIKELIHOOD_MODE)
