    # not a statement about the intrinsic single-event latency. Set NPROC=1 only for
    # latency measurements or debugging. The production default retains the
    # historical multiprocessing behavior.
    NPROC = max(1, _env_int("NPROC", 16))
    N_EVENTS_PER_BATCH = max(1, _env_int("N_EVENTS_PER_BATCH", 100))
    WCSIM_PARTICLE_LABEL = os.environ.get("WCSIM_PARTICLE_LABEL", "muon").strip()
