    def map_raw_pmt(raw):
        value = int(raw)
        if SIM_MAPPING is None:
            return value
        return SIM_MAPPING.get(value + int(WCSIM_PMT_ID_OFFSET))


    def event_from_wcsim(pmts, charges, times):
        n_mpmt = len(WCD.mpmts)
        event = Event(0, 0, n_mpmt)
        inactive = set() if INACTIVE_SLOTS is None else INACTIVE_SLOTS
        for slot in range(n_mpmt):
            module_ok = slot not in inactive and WCD.mpmts[slot] is not None
            event.mpmt_status[slot] = bool(module_ok)
            for pmt in range(event.npmt_per_mpmt):
                event.pmt_status[slot][pmt] = bool(
                    module_ok
                    and pmt < len(WCD.mpmts[slot].pmts)
                    and WCD.mpmts[slot].pmts[pmt] is not None
                )
        for raw, charge, hit_time in zip(pmts, charges, times):
            mapped = map_raw_pmt(raw)
            if mapped is None:
                continue
            slot = int(mapped // 100)
            pmt = int(mapped % 100)
            if 0 <= slot < n_mpmt and 0 <= pmt < event.npmt_per_mpmt and event.pmt_status[slot][pmt]:
                event.hit_charges[slot][pmt].append(float(charge))
                event.hit_times[slot][pmt].append(float(hit_time))
        return event


    def build_observables(event):
        charge = []
        timing = []
        for slot in range(event.n_mpmt):
            if not event.mpmt_status[slot] or WCD.mpmts[slot] is None:
                continue
            for pmt in range(event.npmt_per_mpmt):
                if not event.pmt_status[slot][pmt] or WCD.mpmts[slot].pmts[pmt] is None:
                    continue
                q = np.asarray(event.hit_charges[slot][pmt], dtype=np.float64)
                t = np.asarray(event.hit_times[slot][pmt], dtype=np.float64)
                if q.size == 0 or float(np.sum(q)) <= 0.0:
                    charge.append(0.0)
                    timing.append(np.nan)
                else:
                    total = float(np.sum(q))
                    charge.append(total)
                    timing.append(float(np.sum(q * t) / total))
        return np.asarray(charge), np.asarray(timing)


    def prompt_select(hit_times):
        hit_times = np.asarray(hit_times, dtype=np.float64)
        if PROMPT_MIN_FIXED is not None and PROMPT_MAX_FIXED is not None:
            lo, hi = float(PROMPT_MIN_FIXED), float(PROMPT_MAX_FIXED)
            return np.isfinite(hit_times) & (hit_times >= lo) & (hit_times <= hi), lo, hi
        if hit_times.size == 0:
            return np.zeros(0, dtype=bool), 0.0, 17.0
        counts, edges = np.histogram(hit_times, bins=np.arange(0.0, 2000.0, 1.0))
        peak = int(np.argmax(counts))
        hi = float(edges[min(peak + 5, len(edges) - 1)])
        lo = 0.0
        return np.isfinite(hit_times) & (hit_times > lo) & (hit_times < hi), lo, hi


    def apply_optional_ring_mask(obs_pes, obs_ts):
        if RING_MASK_MODE == "none":
            return obs_pes, obs_ts
        # WCTE historical ring list.  Other detectors should use RING_MASK_MODE=none.
        all_ring = np.arange(0, 106)
        keep = np.isin(np.asarray(PMT_SLOTS, dtype=int), all_ring)
        q = obs_pes.copy()
        t = obs_ts.copy()
        if RING_MASK_MODE in {"pes", "both"}:
            q[~keep] = 0.0
        if RING_MASK_MODE in {"ts", "both"}:
            t[~keep] = np.nan
        return q, t


    def track_length_limits():
        max_range = float(RANGE_LOOKUP.overall_distances_mm[-1])
        detector_diagonal = float(np.linalg.norm(DETECTOR.axis_hi - DETECTOR.axis_lo))
        if FIT_MODE == "full_length" and FULL_LENGTH_CLIP_TO_DETECTOR:
            configured = float(FULL_LENGTH_RANGE_MAX_MM)
            upper = max_range if configured <= 0.0 else min(configured, max_range)
            return float(TRACK_LENGTH_MIN_MM), float(upper)
        configured = float(TRACK_LENGTH_MAX_MM)
        if configured <= 0.0:
            configured = detector_diagonal
        return float(TRACK_LENGTH_MIN_MM), min(configured, max_range, detector_diagonal)



    def resolve_fixed_parameters_after_range_lookup() -> None:
        """Validate mode-specific fixed parameters and convert fixed KE to range."""
        active = (
            {"x0", "y0", "z0", "visible_length", "full_range", "t0", "direction"}
            if FIT_MODE == "absorption"
            else {"x0", "y0", "z0", "length", "t0", "direction"}
        )
        invalid = sorted(set(FIXED_PARAMS) - active)
        if invalid:
            raise ValueError(
                f"Fixed parameter(s) {invalid} are not valid in FIT_MODE={FIT_MODE!r}. "
                f"Valid names are {sorted(active)}"
            )

        if FIXED_KE0_MEV is not None:
            if FIT_MODE != "absorption":
                raise ValueError("FIXED_KE0_MEV is only meaningful in absorption mode")
            ke = float(FIXED_KE0_MEV)
            threshold = float(cherenkov_threshold_kinetic_mev(particle_mass_mev(FIT_PARTICLE)))
            if not math.isfinite(ke) or ke <= threshold:
                raise ValueError(
                    f"FIXED_KE0_MEV={ke!r} must exceed the {FIT_PARTICLE} "
                    f"Cherenkov threshold {threshold:.6g} MeV"
                )
            converted = float(RANGE_LOOKUP.energy_to_range_mm(ke))
            existing = FIXED_PARAMS.get("full_range")
            if existing is not None and not np.isclose(
                float(existing), converted, rtol=1.0e-6, atol=1.0e-6
            ):
                raise ValueError(
                    "FIX_FULL_RANGE and FIXED_KE0_MEV disagree: "
                    f"{existing} mm versus {converted} mm from the range table"
                )
            FIXED_PARAMS["full_range"] = converted

        length_lo, length_hi = track_length_limits()
        if "length" in FIXED_PARAMS and not (
            length_lo <= float(FIXED_PARAMS["length"]) <= length_hi
        ):
            raise ValueError(
                f"FIX_LENGTH={FIXED_PARAMS['length']} lies outside [{length_lo}, {length_hi}] mm"
            )
        if "visible_length" in FIXED_PARAMS and not (
            length_lo <= float(FIXED_PARAMS["visible_length"]) <= length_hi
        ):
            raise ValueError(
                "FIX_VISIBLE_LENGTH lies outside the detector/range limits: "
                f"{FIXED_PARAMS['visible_length']} not in [{length_lo}, {length_hi}] mm"
            )
        if "full_range" in FIXED_PARAMS:
            maximum = float(RANGE_LOOKUP.overall_distances_mm[-1])
            value = float(FIXED_PARAMS["full_range"])
            if not (0.0 < value <= maximum):
                raise ValueError(f"FIX_FULL_RANGE={value} lies outside (0, {maximum}] mm")
        if (
            FIT_MODE == "absorption"
            and "visible_length" in FIXED_PARAMS
            and "full_range" in FIXED_PARAMS
            and float(FIXED_PARAMS["visible_length"]) > float(FIXED_PARAMS["full_range"])
        ):
            raise ValueError("FIX_VISIBLE_LENGTH cannot exceed FIX_FULL_RANGE")
        if "t0" in FIXED_PARAMS and not (
            float(T0_LIMITS[0]) <= float(FIXED_PARAMS["t0"]) <= float(T0_LIMITS[1])
        ):
            raise ValueError(f"FIX_T0 must lie inside T0_LIMITS={T0_LIMITS}")


    def _clean_length_values(values: Sequence[float], maximum: float) -> list[float]:
        lower = max(float(TRACK_LENGTH_MIN_MM), 0.0)
        cleaned = sorted({
            round(float(value), 6)
            for value in values
            if math.isfinite(float(value)) and lower <= float(value) <= float(maximum)
        })
        if not cleaned:
            raise ValueError("The configured seed length grid is empty after physical clipping")
        return [float(value) for value in cleaned]


    def wcte_length_grid() -> tuple[list[float], float]:
        """Energy-independent range seeds plus an optional explicit beam hint."""
        maximum = float(track_length_limits()[1])
        expected_range = float(RANGE_LOOKUP.energy_to_range_mm(WCTE_EXPECTED_KE_MEV))
        if not math.isfinite(expected_range) or expected_range <= 0.0:
            expected_range = min(1000.0, maximum)
        if FIT_MODE == "full_length" and FULL_LENGTH_CLIP_TO_DETECTOR:
            if "length" in FIXED_PARAMS:
                raw = [float(FIXED_PARAMS["length"])]
            elif WCTE_EXPLICIT_LENGTHS_MM:
                raw = [float(value) for value in WCTE_EXPLICIT_LENGTHS_MM]
            else:
                raw = []
                threshold = float(
                    cherenkov_threshold_kinetic_mev(particle_mass_mev(FIT_PARTICLE))
                )
                for kinetic_energy in FULL_LENGTH_RANGE_KE_ANCHORS_MEV:
                    if float(kinetic_energy) <= threshold:
                        continue
                    try:
                        raw.append(float(
                            RANGE_LOOKUP.energy_to_range_mm(float(kinetic_energy))
                        ))
                    except Exception:
                        continue
                # Geometry-derived scales fill gaps between the particle-table
                # anchors without privileging a nominal beam energy.
                diagonal = float(np.linalg.norm(DETECTOR.axis_hi - DETECTOR.axis_lo))
                raw.extend((0.35 * diagonal, 0.65 * diagonal, diagonal))
                if FULL_LENGTH_USE_EXPECTED_ENERGY_HINT:
                    raw.extend(
                        expected_range * float(factor)
                        for factor in WCTE_LENGTH_FACTORS
                    )
                    raw.append(expected_range)
            return _clean_length_values(raw, maximum), expected_range

        if WCTE_EXPLICIT_LENGTHS_MM:
            raw = [float(value) for value in WCTE_EXPLICIT_LENGTHS_MM]
        else:
            raw = [expected_range * float(factor) for factor in WCTE_LENGTH_FACTORS]
            raw.append(expected_range)
        if FIT_MODE == "full_length" and "length" in FIXED_PARAMS:
            raw = [float(FIXED_PARAMS["length"])]
        elif FIT_MODE == "absorption" and "visible_length" in FIXED_PARAMS:
            raw = [float(FIXED_PARAMS["visible_length"])]
        return _clean_length_values(raw, maximum), expected_range


    def absorption_full_range_grid(
        visible_lengths: Sequence[float], *, expected_range_mm: float | None = None
    ) -> list[float]:
        maximum = float(RANGE_LOOKUP.overall_distances_mm[-1])
        if "full_range" in FIXED_PARAMS:
            return [float(FIXED_PARAMS["full_range"])]
        if expected_range_mm is None:
            raw = default_length_grid(
                maximum, fractions=(0.20, 0.35, 0.50, 0.70, 0.90, 1.0), minimum_mm=1.0
            )
        else:
            raw = [expected_range_mm * float(factor) for factor in WCTE_LENGTH_FACTORS]
            raw.extend(float(value) for value in visible_lengths)
            raw.append(expected_range_mm)
        cleaned = sorted({
            round(float(value), 6)
            for value in raw
            if math.isfinite(float(value)) and 0.0 < float(value) <= maximum
        })
        if not cleaned:
            raise ValueError("The absorption full-range seed grid is empty")
        return [float(value) for value in cleaned]


    def _unique_seed_direction_count(seeds: Sequence[Mapping[str, object]]) -> int:
        keys = {
            (
                round(float(seed["dir_x"]), 8),
                round(float(seed["dir_y"]), 8),
                round(float(seed["dir_z"]), 8),
            )
            for seed in seeds
        }
        return int(len(keys))


    def build_seed_library() -> tuple[list[dict[str, object]], dict[str, object]]:
        """Build either the WCTE beam-focused or IWCD detector-global library."""
        full_range_limits = (
            (1.0, float(RANGE_LOOKUP.overall_distances_mm[-1]))
            if FIT_MODE == "absorption" else None
        )

        if WCTE:
            lengths, expected_range = wcte_length_grid()
            full_ranges = (
                absorption_full_range_grid(lengths, expected_range_mm=expected_range)
                if FIT_MODE == "absorption" else None
            )
            beam_direction = normalize_direction(WCTE_BEAM_DIRECTION)
            beam_seeds: list[dict[str, object]] = []
            build_beam_cluster = (
                FIXED_DIRECTION is None
                or float(np.dot(FIXED_DIRECTION, beam_direction))
                >= math.cos(math.radians(20.0))
            )
            if build_beam_cluster:
                beam_offsets = (
                    ((0.0, 0.0),)
                    if FIXED_DIRECTION is not None
                    else WCTE_BEAM_DIRECTION_TANGENT_OFFSETS
                )
                beam_seeds = build_focused_seed_grid(
                    DETECTOR,
                    reference_vertex_mm=WCTE_BEAM_ENTRY_MM,
                    anchor_direction=(
                        FIXED_DIRECTION if FIXED_DIRECTION is not None else beam_direction
                    ),
                    lengths_mm=lengths,
                    longitudinal_offsets_mm=WCTE_BEAM_LONGITUDINAL_OFFSETS_MM,
                    transverse_offsets_mm=WCTE_BEAM_TRANSVERSE_OFFSETS_MM,
                    direction_tangent_offsets=beam_offsets,
                    track_end_mode=FIT_MODE,
                    full_ranges_mm=full_ranges,
                    seed_family="wcte_beam_cluster",
                )
                if FIXED_DIRECTION is None:
                    # Historical sparse WCTE geometry variants: vary vertex or
                    # direction around the beam hypothesis, but do not take their
                    # full Cartesian product.
                    ref = np.asarray(WCTE_BEAM_ENTRY_MM, dtype=np.float64)
                    sparse = []
                    for seed in beam_seeds:
                        point = np.asarray([seed["x0"], seed["y0"], seed["z0"]], dtype=np.float64)
                        dseed = np.asarray([seed["dir_x"], seed["dir_y"], seed["dir_z"]], dtype=np.float64)
                        delta = point - ref
                        transverse = delta - np.dot(delta, beam_direction) * beam_direction
                        vertex_central = np.linalg.norm(transverse) < 1.0e-8
                        direction_central = np.dot(dseed, beam_direction) > 1.0 - 1.0e-12
                        if vertex_central or direction_central:
                            sparse.append(seed)
                    beam_seeds = sparse
                if FIXED_DIRECTION is None and not beam_seeds:
                    raise ValueError(
                        "The WCTE beam seed cluster is empty. Check WCTE_BEAM_ENTRY_MM, "
                        "WCTE_BEAM_DIRECTION, seed lengths, and the loaded geometry."
                    )

            guard_seeds: list[dict[str, object]] = []
            guard_directions = np.empty((0, 3), dtype=np.float64)
            if WCTE_INCLUDE_ORIENTATION_GUARD or FIXED_DIRECTION is not None:
                guard_directions = (
                    np.asarray([FIXED_DIRECTION], dtype=np.float64)
                    if FIXED_DIRECTION is not None
                    else fibonacci_sphere_directions(WCTE_GUARD_DIRECTION_FIBONACCI)
                )
                guard_seeds = build_entry_guard_seed_grid(
                    DETECTOR,
                    guard_directions,
                    lengths,
                    insets_mm=WCTE_GUARD_ENTRY_INSETS_MM,
                    transverse_offsets_mm=WCTE_GUARD_TRANSVERSE_OFFSETS_MM,
                    track_end_mode=FIT_MODE,
                    full_ranges_mm=full_ranges,
                    seed_family="wcte_orientation_guard",
                )

            global_seeds: list[dict[str, object]] = []
            global_metadata: dict[str, object] = {}
            global_lengths: list[float] = []
            global_full_ranges: list[float] | None = None
            if WCTE_INCLUDE_DETECTOR_GLOBAL:
                if FIT_MODE == "full_length" and "length" in FIXED_PARAMS:
                    global_lengths = [float(FIXED_PARAMS["length"])]
                elif FIT_MODE == "absorption" and "visible_length" in FIXED_PARAMS:
                    global_lengths = [float(FIXED_PARAMS["visible_length"])]
                else:
                    maximum = float(track_length_limits()[1])
                    if FIT_MODE == "full_length" and FULL_LENGTH_CLIP_TO_DETECTOR:
                        global_lengths = list(lengths)
                    else:
                        global_lengths = sorted({
                            round(float(expected_range) * float(factor), 6)
                            for factor in WCTE_GLOBAL_LENGTH_FACTORS
                            if math.isfinite(float(factor))
                            and 0.0 < float(expected_range) * float(factor) <= maximum
                        })
                if not global_lengths:
                    raise ValueError("The WCTE detector-global visible-length grid is empty")
                global_full_ranges = (
                    absorption_full_range_grid(
                        global_lengths, expected_range_mm=expected_range
                    )
                    if FIT_MODE == "absorption" else None
                )
                global_directions = (
                    np.asarray([FIXED_DIRECTION], dtype=np.float64)
                    if FIXED_DIRECTION is not None
                    else fibonacci_sphere_directions(WCTE_GLOBAL_DIRECTION_FIBONACCI)
                )
                extra_vertices = []
                if DETECTOR.reference_center is not None:
                    extra_vertices.append(tuple(float(x) for x in DETECTOR.reference_center))
                extra_vertices.append((0.0, 0.0, 0.0))
                global_seeds, global_metadata = build_budgeted_global_seed_grid(
                    DETECTOR,
                    global_directions,
                    global_lengths,
                    track_end_mode=FIT_MODE,
                    full_ranges_mm=global_full_ranges,
                    vertex_spacing_mm=WCTE_GLOBAL_VERTEX_SPACING_MM,
                    wall_margin_mm=WCTE_GLOBAL_WALL_MARGIN_MM,
                    extra_vertices=tuple(extra_vertices),
                    max_total_seeds=WCTE_GLOBAL_MAX_SEEDS,
                )
                for seed in global_seeds:
                    seed["seed_family"] = "wcte_detector_global"

            seeds = filter_seed_grid_for_fixed_parameters(
                beam_seeds + guard_seeds + global_seeds,
                DETECTOR,
                track_end_mode=FIT_MODE,
                fixed_params=FIXED_PARAMS,
                fixed_direction=FIXED_DIRECTION,
                full_range_limits=full_range_limits,
            )
            metadata = {
                "strategy": "wcte_beam_focused_plus_detector_global",
                "expected_ke_mev": float(WCTE_EXPECTED_KE_MEV),
                "expected_range_mm": float(expected_range),
                "beam_entry_mm": np.asarray(WCTE_BEAM_ENTRY_MM, dtype=float).tolist(),
                "beam_direction": beam_direction.tolist(),
                "visible_lengths_mm": [float(value) for value in lengths],
                "full_ranges_mm": None if full_ranges is None else [float(value) for value in full_ranges],
                "beam_seed_count_before_fixed_filter": int(len(beam_seeds)),
                "guard_seed_count_before_fixed_filter": int(len(guard_seeds)),
                "guard_direction_count": int(guard_directions.shape[0]),
                "orientation_guard_enabled": bool(WCTE_INCLUDE_ORIENTATION_GUARD),
                "detector_global_enabled": bool(WCTE_INCLUDE_DETECTOR_GLOBAL),
                "detector_global_seed_count_before_fixed_filter": int(len(global_seeds)),
                "detector_global_visible_lengths_mm": [float(value) for value in global_lengths],
                "detector_global_full_ranges_mm": (
                    None if global_full_ranges is None
                    else [float(value) for value in global_full_ranges]
                ),
                "detector_global_metadata": dict(global_metadata),
                "seed_count": int(len(seeds)),
                "direction_count": _unique_seed_direction_count(seeds),
            }
            return seeds, metadata

        maximum = float(track_length_limits()[1])
        lengths = (
            [float(FIXED_PARAMS["length"])]
            if FIT_MODE == "full_length" and "length" in FIXED_PARAMS
            else [float(FIXED_PARAMS["visible_length"])]
            if FIT_MODE == "absorption" and "visible_length" in FIXED_PARAMS
            else default_length_grid(maximum, fractions=IWCD_LENGTH_FRACTIONS)
        )
        directions = (
            np.asarray([FIXED_DIRECTION], dtype=np.float64)
            if FIXED_DIRECTION is not None
            else fibonacci_sphere_directions(IWCD_DIRECTION_FIBONACCI_COUNT)
        )
        full_ranges = absorption_full_range_grid(lengths) if FIT_MODE == "absorption" else None
        seeds, metadata = build_budgeted_global_seed_grid(
            DETECTOR,
            directions,
            lengths,
            track_end_mode=FIT_MODE,
            full_ranges_mm=full_ranges,
            vertex_spacing_mm=IWCD_VERTEX_GRID_SPACING_MM,
            wall_margin_mm=IWCD_VERTEX_GRID_WALL_MARGIN_MM,
            max_total_seeds=IWCD_GLOBAL_MAX_SEEDS,
        )
        seeds = filter_seed_grid_for_fixed_parameters(
            seeds,
            DETECTOR,
            track_end_mode=FIT_MODE,
            fixed_params=FIXED_PARAMS,
            fixed_direction=FIXED_DIRECTION,
            full_range_limits=full_range_limits,
        )
        metadata = dict(metadata)
        metadata.update({
            "strategy": "iwcd_budgeted_detector_global",
            "visible_lengths_mm": [float(value) for value in lengths],
            "full_ranges_mm": None if full_ranges is None else [float(value) for value in full_ranges],
            "seed_count_after_fixed_filter": int(len(seeds)),
            "direction_count_after_fixed_filter": _unique_seed_direction_count(seeds),
        })
        return seeds, metadata



    def seed_values_and_chart_for_fit(seed):
        """Use a beam-axis chart for focused WCTE seeds; arbitrary seeds keep their own chart."""
        values, chart = seed_values_from_mapping(seed, track_end_mode=FIT_MODE)
        if WCTE and str(seed.get("seed_family", "")) == "wcte_beam_cluster":
            beam_chart = TangentDirectionChart.from_direction(WCTE_BEAM_DIRECTION)
            direction = normalize_direction((seed["dir_x"], seed["dir_y"], seed["dir_z"]))
            coordinates = beam_chart.coordinates(direction)
            if coordinates is None:
                raise ValueError("focused WCTE seed is outside the beam-axis tangent chart")
            values["dir_u"], values["dir_v"] = map(float, coordinates)
            chart = beam_chart
        return values, chart


    def make_objective(obs_pes, obs_ts, chart, mode, *, proxy=False):
        emitter = EMITTER_TEMPLATE.copy()
        if proxy:
            if PROXY_DISABLE_PHOTON_SCATTER:
                emitter.enable_rayleigh_scatter = False
            if PROXY_DISABLE_DELTA:
                emitter.enable_delta_e = False
        return TrackObjective(
            emitter=emitter,
            wcd=WCD,
            pmt_model=PMT_MODEL,
            p_locations=P_LOCATIONS,
            pmt_normals=PMT_NORMALS,
            obs_pes=np.asarray(obs_pes, dtype=np.float64),
            obs_ts=np.asarray(obs_ts, dtype=np.float64),
            chart=chart,
            detector=DETECTOR,
            objective_mode=mode,
            track_end_mode=FIT_MODE,
            range_lookup=RANGE_LOOKUP,
            particle_threshold_mev=cherenkov_threshold_kinetic_mev(particle_mass_mev(FIT_PARTICLE)),
            t0_limits=T0_LIMITS,
            require_contained_track=True,
            clip_full_length_to_boundary=bool(
                FIT_MODE == "full_length" and FULL_LENGTH_CLIP_TO_DETECTOR
            ),
            boundary_clip_inset_mm=float(FULL_LENGTH_BOUNDARY_INSET_MM),
        )


    def _resolved_full_length_output(values):
        """Return visible support/topology for the public full_length result."""
        out = dict(values)
        if FIT_MODE != "full_length":
            return out, None
        full_range = float(out.get("full_range", out.get("length", math.nan)))
        direction = normalize_direction((out["cx"], out["cy"], out["cz"]))
        vertex = np.asarray([out["x0"], out["y0"], out["z0"]], dtype=np.float64)
        raw_distance = float(DETECTOR.ray_exit_distance(vertex, direction))
        if not math.isfinite(raw_distance) or raw_distance < 0.0:
            return out, None
        if FULL_LENGTH_CLIP_TO_DETECTOR:
            inset = min(
                float(FULL_LENGTH_BOUNDARY_INSET_MM),
                max(0.0, raw_distance - 1.0e-6),
            )
            distance = float(raw_distance - inset)
        else:
            distance = float(raw_distance)
        visible = min(full_range, distance) if FULL_LENGTH_CLIP_TO_DETECTOR else full_range
        exits = bool(FULL_LENGTH_CLIP_TO_DETECTOR and full_range >= distance - 1.0e-6)
        out["length"] = full_range
        out["full_range"] = full_range
        out["visible_length"] = float(visible)
        out["distance_to_boundary"] = float(distance)
        out["topology_margin"] = float(full_range - distance)
        out["track_topology"] = (
            "internal_start_boundary_exit" if exits
            else "internal_start_internal_stop"
        )
        out["exits_detector"] = exits
        out["ke0"] = float(RANGE_LOOKUP.range_mm_to_energy(full_range))
        return out, {
            "full_range_mm": full_range,
            "visible_length_mm": float(visible),
            "distance_to_boundary_mm": float(distance),
            "exits_detector": exits,
            "topology": out["track_topology"],
        }


    def _profile_full_length_range(obs_pes, obs_ts, values, current_fval):
        """Energy-label-blind fixed-line range profile for full_length mode.

        Charge screens a broad deterministic range bank.  Only a compact set is
        closed with the unchanged joint likelihood and profiled event time.
        This preserves standard-mode latency while resolving exiting-particle
        energy and reporting genuinely open high-range profiles.
        """
        disabled = {
            "enabled": False,
            "reason": "not_applicable",
            "range_constraint_status": "not_applicable",
            "rows": [],
        }
        if (
            FIT_MODE != "full_length"
            or not FULL_LENGTH_CLIP_TO_DETECTOR
            or not FULL_LENGTH_ENABLE_RANGE_PROFILE
        ):
            return dict(values), float(current_fval), disabled, 0
        if "length" in FIXED_PARAMS:
            return dict(values), float(current_fval), {
                **disabled, "reason": "full_range_fixed",
            }, 0
        try:
            output, summary = _resolved_full_length_output(values)
        except Exception:
            return dict(values), float(current_fval), {
                **disabled, "reason": "invalid_current_track",
            }, 0
        if summary is None:
            return dict(values), float(current_fval), {
                **disabled, "reason": "invalid_current_track",
            }, 0
        direction = normalize_direction((output["cx"], output["cy"], output["cz"]))
        chart = TangentDirectionChart.from_direction(direction)
        base = {
            "x0": float(output["x0"]),
            "y0": float(output["y0"]),
            "z0": float(output["z0"]),
            "dir_u": 0.0,
            "dir_v": 0.0,
            "length": float(output["full_range"]),
            "t0": float(output.get("t0", 0.0)),
        }
        lower, upper = track_length_limits()
        boundary = float(summary["distance_to_boundary_mm"])
        current_range = float(summary["full_range_mm"])
        anchors = {current_range, max(lower, min(upper, boundary * 0.985)),
                   max(lower, min(upper, boundary * 1.015)), upper}
        for factor in (0.65, 0.82, 1.0, 1.22, 1.55):
            anchors.add(max(lower, min(upper, current_range * factor)))
        threshold = float(
            cherenkov_threshold_kinetic_mev(particle_mass_mev(FIT_PARTICLE))
        )
        for kinetic_energy in FULL_LENGTH_RANGE_PROFILE_KE_ANCHORS_MEV:
            if float(kinetic_energy) <= threshold:
                continue
            try:
                anchors.add(max(lower, min(
                    upper,
                    float(RANGE_LOOKUP.energy_to_range_mm(float(kinetic_energy))),
                )))
            except Exception:
                pass
        ranges = sorted({
            round(float(x), 7) for x in anchors
            if math.isfinite(float(x)) and lower <= float(x) <= upper
        })
        charge_obj = make_objective(
            obs_pes, obs_ts, chart, "charge_only", proxy=False
        )
        screening = []
        for full_range in ranges:
            trial = dict(base); trial["length"] = float(full_range)
            fval = float(charge_obj(trial))
            if math.isfinite(fval):
                screening.append({
                    "full_range_mm": float(full_range),
                    "charge_fval": fval,
                })
        if not screening:
            return dict(values), float(current_fval), {
                **disabled, "enabled": True, "reason": "no_finite_range_points",
                "range_constraint_status": "profile_failed",
            }, int(charge_obj.evaluations)
        screening.sort(key=lambda row: row["charge_fval"])
        # Close the best charge anchors plus physically diagnostic current,
        # boundary-neighbour and table-limit points.
        keep = {row["full_range_mm"] for row in screening[:5]}
        for target in (current_range, boundary * 0.985, boundary * 1.015, upper):
            closest = min(
                screening,
                key=lambda row: abs(row["full_range_mm"] - float(target)),
            )
            keep.add(float(closest["full_range_mm"]))
        exact_obj = make_objective(
            obs_pes, obs_ts, chart, LIKELIHOOD_MODE, proxy=False
        )
        rows = []
        for row in screening:
            if float(row["full_range_mm"]) not in keep:
                continue
            trial = dict(base); trial["length"] = float(row["full_range_mm"])
            if LIKELIHOOD_MODE == "charge_only" or "t0" in FIXED_PARAMS:
                fval = float(exact_obj(trial)); t0 = float(trial["t0"])
            else:
                prof = profile_t0(
                    exact_obj,
                    trial,
                    limits=T0_LIMITS,
                    coarse_step_ns=T0_PROFILE_COARSE_STEP_NS,
                    refine_levels=T0_PROFILE_REFINE_LEVELS,
                    refine_factor=T0_PROFILE_REFINE_FACTOR,
                )
                fval = float(prof.fval); t0 = float(prof.values["t0"])
            if math.isfinite(fval):
                rows.append({
                    "full_range_mm": float(row["full_range_mm"]),
                    "ke0_mev": float(RANGE_LOOKUP.range_mm_to_energy(row["full_range_mm"])),
                    "charge_fval": float(row["charge_fval"]),
                    "fval": fval,
                    "t0_ns": t0,
                })
        # One exact bounded log-parabolic refinement around the best closed row.
        candidate = safeguarded_log_parabolic_range_candidate(
            rows, lower, upper,
            range_key="full_range_mm", objective_key="fval",
        )
        if candidate is not None:
            trial = dict(base); trial["length"] = float(candidate)
            if LIKELIHOOD_MODE == "charge_only" or "t0" in FIXED_PARAMS:
                fval = float(exact_obj(trial)); t0 = float(trial["t0"])
            else:
                prof = profile_t0(
                    exact_obj, trial, limits=T0_LIMITS,
                    coarse_step_ns=T0_PROFILE_COARSE_STEP_NS,
                    refine_levels=T0_PROFILE_REFINE_LEVELS,
                    refine_factor=T0_PROFILE_REFINE_FACTOR,
                )
                fval = float(prof.fval); t0 = float(prof.values["t0"])
            if math.isfinite(fval):
                rows.append({
                    "full_range_mm": float(candidate),
                    "ke0_mev": float(RANGE_LOOKUP.range_mm_to_energy(candidate)),
                    "charge_fval": None, "fval": fval, "t0_ns": t0,
                    "refinement": True,
                })
        rows.sort(key=lambda row: row["full_range_mm"])
        if not rows:
            return dict(values), float(current_fval), {
                **disabled, "enabled": True, "reason": "no_finite_exact_points",
                "range_constraint_status": "profile_failed",
            }, int(charge_obj.evaluations + exact_obj.evaluations)
        best = min(rows, key=lambda row: row["fval"])
        high = max(rows, key=lambda row: row["full_range_mm"])
        best_f = float(best["fval"])
        high_delta = float(high["fval"] - best_f)
        weak = float(FULL_LENGTH_RANGE_PROFILE_WEAK_DELTA_NLL)
        best_range = float(best["full_range_mm"])
        if high["full_range_mm"] >= 0.95 * upper and high_delta <= weak:
            status = "open_high_at_range_table_limit"
        elif best_range >= boundary and high_delta <= weak:
            status = "lower_bound_or_weak_high_side"
        elif best_range < boundary:
            status = "endpoint_constrained"
        else:
            status = "profiled_local_minimum"
        updated = dict(output)
        # The fixed-line exact profile is authoritative for the range coordinate.
        # Keep the accepted geometry and update only range/t0.
        updated["length"] = best_range
        updated["full_range"] = best_range
        updated["t0"] = float(best["t0_ns"])
        updated, updated_summary = _resolved_full_length_output(updated)
        payload = {
            "enabled": True,
            "reason": "energy_independent_fixed_line_profile",
            "fixed_geometry_profile": True,
            "rows": rows,
            "current_full_range_mm": current_range,
            "distance_to_boundary_mm": boundary,
            "best_full_range_mm": best_range,
            "best_ke0_mev": float(best["ke0_mev"]),
            "best_fval": best_f,
            "best_t0_ns": float(best["t0_ns"]),
            "high_side_delta_nll": high_delta,
            "range_constraint_status": status,
            "updated_track": updated_summary,
            "uses_expected_energy_hint": bool(FULL_LENGTH_USE_EXPECTED_ENERGY_HINT),
            "uses_event_truth": False,
        }
        return updated, best_f, payload, int(
            charge_obj.evaluations + exact_obj.evaluations
        )


    def predict_proxy_shape(seed):
        values, chart = seed_values_and_chart_for_fit(seed)
        emitter = EMITTER_TEMPLATE.copy()
        if PROXY_DISABLE_PHOTON_SCATTER:
            emitter.enable_rayleigh_scatter = False
        if PROXY_DISABLE_DELTA:
            emitter.enable_delta_e = False
        direction = chart.anchor
        emitter.start_coord = (values["x0"], values["y0"], values["z0"])
        emitter.direction = tuple(float(x) for x in direction)
        emitter.starting_time = 0.0
        if FIT_MODE == "absorption":
            emitter.configure_track_end(
                "abrupt",
                fixed_initial_KE=float(
                    RANGE_LOOKUP.range_mm_to_energy(values["full_range"])
                ),
                refresh=False,
            )
            length = values["visible_length"]
        elif FULL_LENGTH_CLIP_TO_DETECTOR:
            full_range = float(values["length"])
            ke0 = float(RANGE_LOOKUP.range_mm_to_energy(full_range))
            emitter.configure_track_end("abrupt", fixed_initial_KE=ke0, refresh=False)
            distance = float(DETECTOR.ray_exit_distance(
                values_vertex := np.asarray(
                    [values["x0"], values["y0"], values["z0"]], dtype=np.float64
                ),
                direction,
            ))
            if not math.isfinite(distance) or distance <= 0.0:
                return np.zeros(len(P_LOCATIONS), dtype=np.float64)
            inset = min(
                float(FULL_LENGTH_BOUNDARY_INSET_MM),
                max(0.0, distance - 1.0e-6),
            )
            length = min(full_range, float(distance - inset))
        else:
            emitter.configure_track_end("threshold", fixed_initial_KE=None, refresh=False)
            length = values["length"]
        init_ke = emitter.refresh_kinematics_from_length(length)
        emission = emitter.get_emission_points(P_LOCATIONS, init_ke)
        dummy = np.ones(len(P_LOCATIONS), dtype=np.float64)
        emitter.get_expected_pes_ts(WCD, emission, P_LOCATIONS, PMT_NORMALS, None, dummy, need_times=False)
        shape = np.asarray(emitter._last_expected_pes_unfloored, dtype=np.float64)
        return np.where(np.isfinite(shape) & (shape > 0.0), shape, 0.0)


    def proxy_path(metadata):
        if PROXY_LIBRARY_OVERRIDE:
            return Path(PROXY_LIBRARY_OVERRIDE).expanduser()
        return TABLE_DIR / (
            f"{DETECTOR_MODE.lower()}_track_proxy_"
            f"{str(metadata['digest'])[:16]}_v3.npz"
        )


    def _array_sha256(array) -> str:
        return hashlib.sha256(np.ascontiguousarray(array).tobytes()).hexdigest()


    def _proxy_emitter_configuration() -> dict[str, object]:
        """Return every resolved setting that can change a proxy charge shape.

        The proxy cache filename must change when a user changes physics through an
        environment variable without editing Emitter.py.  Source-file hashing alone
        does not catch those runtime settings.  Keep this signature deliberately
        redundant: a one-time cache rebuild is much safer than reusing a shape table
        produced with different endpoint, MCS, delta, scattering, or reflection
        physics.
        """
        emitter = EMITTER_TEMPLATE
        proxy_delta = bool(getattr(emitter, "enable_delta_e", False)) and not bool(
            PROXY_DISABLE_DELTA
        )
        proxy_scatter = bool(
            getattr(emitter, "enable_rayleigh_scatter", False)
        ) and not bool(PROXY_DISABLE_PHOTON_SCATTER)
        names = (
            "n",
            "intensity",
            "particle_name",
            "particle_mass",
            "track_end_mode",
            "primary_endpoint_model",
            "primary_endpoint_scope",
            "primary_endpoint_aperture_radius_mm",
            "primary_edge_model",
            "primary_cost_soft",
            "primary_cost_soft_centered",
            "primary_soft_cone_sigma_rad",
            "primary_mcs_model",
            "primary_mcs_energy_mode",
            "primary_mcs_energy_samples",
            "primary_mcs_radiation_length_mm",
            "primary_mcs_charge_number",
            "delta_e_scale",
            "analytic_delta_scale",
            "delta_e_distance_pmt_radius_mm",
            "delta_e_cost_soft",
            "smooth_tables",
            "use_subgrid_refine",
            "photon_scatter_model",
            "photon_scatter_spectral_mode",
            "photon_scatter_n_track",
            "photon_scatter_n_azimuth",
            "photon_scatter_n_interaction",
            "photon_scatter_n_wavelength",
            "photon_scatter_n_raman_shift",
            "photon_scatter_enable_raman",
            "photon_scatter_direct_survival",
            "photon_scatter_include_mpmt_domes",
            "photon_scatter_boundary_model",
            "reflection_in_charge",
            "reflection_bsrff",
            "reflection_pmt_aperture_radius_mm",
            "charge_normalization_mode",
            "global_charge_scale",
        )
        configuration: dict[str, object] = {
            "proxy_enable_delta_e": proxy_delta,
            "proxy_enable_primary_mcs_smearing": bool(
                getattr(emitter, "enable_primary_mcs_smearing", False)
            ),
            "proxy_enable_molecular_scattering": proxy_scatter,
            "proxy_enable_blacksheet_reflection": bool(
                getattr(emitter, "enable_blacksheet_reflection", False)
            ),
        }
        for name in names:
            value = getattr(emitter, name, None)
            if isinstance(value, np.generic):
                value = value.item()
            if isinstance(value, (str, bool, int, float)) or value is None:
                configuration[name] = value
            else:
                configuration[name] = repr(value)
        return configuration



    def resolved_physics_configuration() -> dict[str, object]:
        emitter = EMITTER_TEMPLATE
        return {
            "delta_e": bool(getattr(emitter, "enable_delta_e", False)),
            "primary_mcs_enabled": bool(getattr(emitter, "enable_primary_mcs", False)),
            "primary_mcs_mode": str(MCS_RECONSTRUCTION_MODE),
            "primary_mcs_smearing": bool(getattr(emitter, "enable_primary_mcs_smearing", False)),
            "molecular_scattering": bool(getattr(emitter, "enable_rayleigh_scatter", False)),
            "blacksheet_reflection": bool(getattr(emitter, "enable_blacksheet_reflection", False)),
            "reflection_in_charge": bool(getattr(emitter, "reflection_in_charge", False)),
            "first_arrival_timing": bool(getattr(emitter, "use_first_arrival_timing", False)),
            "reflection_occupancy_guard": bool(
                getattr(PMT_MODEL, "first_arrival_reflection_occupancy_mix", False)
            ),
            "reflection_direct_support_scale_pe": float(
                getattr(PMT_MODEL, "first_arrival_direct_support_scale_pe", math.nan)
            ),
            "endpoint_model": str(getattr(emitter, "primary_endpoint_model", "")),
            "endpoint_aperture_radius_mm": float(getattr(emitter, "primary_endpoint_aperture_radius_mm", math.nan)),
            "endpoint_scope": str(getattr(emitter, "primary_endpoint_scope", "")),
            "joint_exact_sweeps": int(JOINT_EXACT_SWEEPS),
            "adaptive_exact_polish": bool(ADAPTIVE_EXACT_POLISH),
            "stable_prompt_window_gaussian_tails": True,
        }


    def setup_print(*args, **kwargs):
        """Print detailed setup diagnostics only when explicitly requested."""
        if VERBOSE_SETUP:
            print(*args, **kwargs)


    def prepare_proxy_library():
        proxy_seed_grid_metadata = dict(SEED_GRID_METADATA)
        if (
            FIT_MODE == "full_length"
            and FULL_LENGTH_CLIP_TO_DETECTOR
            and not FULL_LENGTH_USE_EXPECTED_ENERGY_HINT
        ):
            # The sample-energy label is intentionally not part of the
            # mandatory seed grid. Excluding it from the cache signature lets
            # physically identical universal seed banks share one deterministic
            # proxy library across differently labelled data sets.
            proxy_seed_grid_metadata.pop("expected_ke_mev", None)
            proxy_seed_grid_metadata.pop("expected_range_mm", None)
            proxy_seed_grid_metadata["expected_energy_used_as_seed_hint"] = False
        metadata, matrix = proxy_library_metadata(
            SEEDS,
            track_end_mode=FIT_MODE,
            p_locations=P_LOCATIONS,
            pmt_normals=PMT_NORMALS,
            particle=FIT_PARTICLE,
            group_index=PROXY_GROUP_INDEX,
            quantization_bits=PROXY_QUANTIZATION_BITS,
            source_files=[
                __file__,
                LICKETYFIT_DIR / "track_parameterization.py",
                LICKETYFIT_DIR / "fast_track_fit.py",
                LICKETYFIT_DIR / "cosmic_track_fit.py",
                LICKETYFIT_DIR / "detector_geometry.py",
                LICKETYFIT_DIR / "Emitter.py",
                LICKETYFIT_DIR / "particle_cherenkov_model.py",
                # Hash the complete range-table files, not only their initial
                # energy/range projections. Primary cone collapse and N_geo can
                # depend on the full K(s) trajectories.
                Path(RANGE_LOOKUP.e_vs_dist_path),
                Path(RANGE_LOOKUP.overall_distances_path),
                TABLE_DIR / "cherenkov_angle_vs_E_muon_n1344.npy",
                TABLE_DIR / "mu_cAng_vs_E_n1344.npy",
            ],
            extra={
                "driver": "batch_fit_driver_wcsim",
                "detector_mode": str(DETECTOR_MODE),
                "proxy_disable_delta": bool(PROXY_DISABLE_DELTA),
                "proxy_disable_photon_scatter": bool(PROXY_DISABLE_PHOTON_SCATTER),
                "proxy_optimize_length": bool(PROXY_OPTIMIZE_LENGTH),
                "seed_grid_metadata": proxy_seed_grid_metadata,
                "proxy_group_mode": str(PROXY_GROUP_MODE),
                "mcs_reconstruction_mode": str(MCS_RECONSTRUCTION_MODE),
                "proxy_emitter_configuration": _proxy_emitter_configuration(),
                "range_initial_energies_sha256": _array_sha256(
                    RANGE_LOOKUP.initial_energies_mev
                ),
                "range_distances_sha256": _array_sha256(
                    RANGE_LOOKUP.overall_distances_mm
                ),
            },
        )
        path = proxy_path(metadata)
        if path.exists():
            try:
                library = QuantizedSeedProxyLibrary.load(path, expected_metadata=metadata)
                setup_print(f"Loaded global proxy library: {path} ({library.memory_bytes/1e6:.1f} MB)")
                return library
            except Exception as exc:
                setup_print(f"Ignoring incompatible proxy library {path}: {exc}")
        wall = time.perf_counter()
        library = build_quantized_proxy_library(
            SEEDS,
            predict_proxy_shape,
            metadata=metadata,
            seed_matrix=matrix,
            group_index=PROXY_GROUP_INDEX,
            quantization_bits=PROXY_QUANTIZATION_BITS,
            progress_every=PROXY_PROGRESS_EVERY,
        )
        library.save(path)
        setup_print(f"Built global proxy library in {time.perf_counter()-wall:.2f} s: {path} ({library.memory_bytes/1e6:.1f} MB)")
        return library


    def block_result_payload(result: BlockOptimizerResult):
        payload = {
            "values": result.output_values(),
            "fval": float(result.fval),
            "nfcn": int(result.nfcn),
            "wall_s": float(result.wall_s),
            "invalid_evaluations": int(result.invalid_evaluations),
            "quadratic_skips": int(result.quadratic_skips),
        }
        if SAVE_DETAILED_EVENT_RESULTS:
            payload["history"] = result.history
        return payload


