    # The driver prints the resolved process state at startup.

    # This is the real-WCTE adapter. The geometry/navigation code below deliberately
    # remains the same WCTE branch used by the current WCSim driver.
    WCTE = True
    IWCD = False
    DETECTOR_MODE = "WCTE"

    # Run and selected-event input.
    RUN = _env_int("RUN", 2079)
