    WCTE_INCLUDE_ORIENTATION_GUARD = _env_bool("WCTE_INCLUDE_ORIENTATION_GUARD", True)
    WCTE_GUARD_DIRECTION_FIBONACCI = _env_int("WCTE_GUARD_DIRECTION_FIBONACCI", 14)
