    def _multiprocessing_smoke_worker(value):
        """Top-level worker used only by --multiprocessing-smoke-test."""
        return {"value": int(value), "square": int(value) * int(value), "pid": int(os.getpid())}


    def run_multiprocessing_smoke_test():
        """Prove that this exact file creates multiple worker processes.

        This path exits before importing Geometry or any fitter module, so it can be
        run immediately after copying the file:

            python batch_fit_driver_wcsim_WCTE_IWCD_MULTIPROCESS.py \
                --multiprocessing-smoke-test
        """
        if "fork" not in mp.get_all_start_methods():
            raise RuntimeError("This production driver requires fork multiprocessing")
        nworkers = max(2, min(4, int(NPROC)))
        values = list(range(max(8, 2 * nworkers)))
        context = mp.get_context("fork")
        with context.Pool(processes=nworkers) as pool:
            rows = pool.map(_multiprocessing_smoke_worker, values, chunksize=1)
        pids = sorted({int(row["pid"]) for row in rows})
        print("Driver release:", DRIVER_RELEASE)
        print("Requested smoke-test workers:", nworkers)
        print("Distinct worker PIDs:", pids)
        print("Results:", rows)
        if len(pids) < 2:
            raise RuntimeError("Multiprocessing smoke test used fewer than two worker processes")
        print("MULTIPROCESSING SMOKE TEST PASSED")


    if __name__ == "__main__" and "--multiprocessing-smoke-test" in sys.argv:
        run_multiprocessing_smoke_test()
