        transverse_mm=_env_float("TIMING_TRANSVERSE_STEP_MM", 30.0),
        direction_tangent=_env_float("TIMING_DIRECTION_TANGENT_STEP", 0.025),
        length_mm=_env_float("TIMING_LENGTH_STEP_MM", 60.0),
