    def _coerce_event_array(event, *, event_label="event"):
        return coerce_user_event_array(
            event,
            event_label=event_label,
            strict=bool(
                STRICT_USER_EVENT_VALIDATION if EVENT_SOURCE == "file" else True
            ),
        )


    def _events_from_loaded_object(obj):
        if isinstance(obj, dict):
            if USER_EVENT_KEY is not None:
                obj = obj[USER_EVENT_KEY]
            elif "events" in obj:
                obj = obj["events"]
            elif "data" in obj:
                obj = obj["data"]
            elif "arr_0" in obj:
                obj = obj["arr_0"]
            else:
                raise KeyError(
                    "Could not choose an event array from the dictionary payload; "
                    f"available keys are {list(obj.keys())}. Set USER_EVENT_KEY."
                )

        if isinstance(obj, np.lib.npyio.NpzFile):
            if USER_EVENT_KEY is not None:
                key = USER_EVENT_KEY
            elif "events" in obj.files:
                key = "events"
            elif "data" in obj.files:
                key = "data"
            elif "arr_0" in obj.files:
                key = "arr_0"
            elif len(obj.files) == 1:
                key = obj.files[0]
            else:
                raise KeyError(
                    "Could not choose an event array from the npz payload; "
                    f"available keys are {obj.files}. Set USER_EVENT_KEY."
                )
            obj = obj[key]

        if isinstance(obj, (list, tuple)):
            return [
                _coerce_event_array(event, event_label=f"event[{index}]")
                for index, event in enumerate(obj)
            ]

        array = np.asarray(
            obj, dtype=object if getattr(obj, "dtype", None) == object else None
        )
        if array.dtype == object and array.ndim == 1:
            return [
                _coerce_event_array(event, event_label=f"event[{index}]")
                for index, event in enumerate(array)
            ]
        if array.ndim == 3:
            return [
                _coerce_event_array(array[index], event_label=f"event[{index}]")
                for index in range(array.shape[0])
            ]
        if array.ndim == 2:
            array = np.asarray(array, dtype=np.float64)
            if array.shape[1] >= 4:
                # In a legacy four-column table column 3 is the event identity.
                # In the DataLoader five-column contract it is the raw ROOT entry
                # index, which is the safest unique grouping key even when the
                # production event_number is repeated across subruns/spills.
                event_keys = array[:, 3]
                finite = np.isfinite(event_keys)
                if not np.all(finite):
                    raise ValueError("The user event-identity column contains non-finite values")
                ordered_ids = []
                seen = set()
                for value in event_keys:
                    key = int(value)
                    if key not in seen:
                        seen.add(key)
                        ordered_ids.append(key)
                return [
                    _coerce_event_array(
                        array[event_keys.astype(np.int64) == event_id],
                        event_label=f"event_identity={event_id}",
                    )
                    for event_id in ordered_ids
                ]
            return [_coerce_event_array(array, event_label="single_event")]
        raise ValueError(
            "Unsupported USER_EVENT_FILE payload. Expected a list/object array of "
            "event arrays, a 3D event array, or a 2D hit table."
        )


    def load_user_event_file(path, *, max_events=None):
        global WCTE_DATA_LOADER_METADATA
        events, metadata = load_validated_user_event_file(
            path,
            user_event_key=USER_EVENT_KEY,
            max_events=max_events,
            strict=bool(STRICT_USER_EVENT_VALIDATION),
            trusted_internal=bool(INTERNAL_PREPARED_EVENT_FILE),
        )
        WCTE_DATA_LOADER_METADATA = dict(metadata)
        print(f"Loaded {len(events)} already-selected WCTE events from: {path}")
        return events


